using System.Diagnostics.Tracing;
using System.Globalization;
using FluentTaskScheduler.History;

namespace FluentTaskScheduler.Tests.History;

/// <summary>
/// The Task Scheduler operational log exactly as a Windows Server runner wrote it while
/// Integration/OperationalLogEvidence went through its scenarios: every record of that period,
/// in log order, with the fields each event really carries. The task names say which scenario a
/// record belongs to. The Folder constant and the records are that test's output, pasted in.
/// </summary>
internal static class Evidence
{
    public const string Folder = @"\FtsTests_a070dc65";

    /// <summary>The records that name the given scenario task.</summary>
    public static IReadOnlyList<LogRecord> Of(string taskName) =>
        Log.Where(record => record.Data.GetValueOrDefault("TaskName") == Folder + "\\" + taskName).ToList();

    private static LogRecord R(long recordId, string time, int id, int level, params string[] data)
    {
        var fields = new Dictionary<string, string>();
        for (int i = 0; i < data.Length; i += 2) fields[data[i]] = data[i + 1];
        var at = DateTimeOffset.Parse(time, CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal);
        return new LogRecord("Microsoft-Windows-TaskScheduler", id, at, fields) { RecordId = recordId, Level = (EventLevel)level };
    }

